FBDMC_Reset(ePLCKernalSta *Task, Uint32 FBIndex,struct MC_Reset *FB){
/*Separator--*--Separator--*--Separator*/
//FBDMC_Reset
#ifndef _CASS_PRECOMPILE_




//20240901修改位置相关变量单精度为双精度，包括引脚和临时变量

uint8_t *state = (uint8_t*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + STATE]);
uint8_t *AxisEnable = (uint8_t*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + AXIS_ENABLE]);
uint8_t *run_numberm = (uint8_t*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + RUN_NUMBERM]);
unsigned short *driver_controlword = (unsigned short*)(&CassMem[DRIVER_BASE + DRIVER_SIZE * FB->Axis_num + DRIVER_CONTROLWORD]);
unsigned short *statusword = (unsigned short*)(&CassMem[DRIVER_BASE + DRIVER_SIZE * FB->Axis_num + DRIVER_STATUSWORD]);
uint8_t *rstflag = (uint8_t*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + RST_FLAG]);
uint8_t *couping_mode = (uint8_t*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + COUPING_MODE]);

uint8_t *torque_run_numberm = (uint8_t*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + TORQUE_RUN_NUMBER]);

float *now_velocity_s = (float*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + NOW_VELOCITY_S]);

uint8_t *axis_busy = (uint8_t*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + AXIS_BUSY]);

int32_t *now_motion_direction = (int32_t*)(&CassMem[AXIS_BASE + AXIS_SIZE*FB->Axis_num + NOW_MOTION_DIRECTION]);
float *blending_v = (float*)(&CassMem[AXIS_BASE + AXIS_SIZE*FB->Axis_num + BLENDING_V]);
float *now_motion_vel = (float*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + NOW_MOTION_VEL]);
uint8_t *buffered_without_blending = (uint8_t*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + BUFFERED_WITHOUT_BLENDING]);
uint8_t *buffer_busy = (uint8_t*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + BUFFER_BUSY]);

Uint8 busy;
//结构体里没有busy变量。只能从exebef变量的字节中借一个！！！功能块的结构是定死的，没法加变量！！！！！
busy = (FB->execute_before >> 7);/* 2022年4月12日 modi 因为没有busy可用，暂时将exebef（execute_before）的最高位当作busy，只将rstflag = 1，表示向smallsystem发送复位请求，由smallsystem完成复位动作 */
FB->execute_before &= 0x7f;

if(!FB->Execute)//不在被使用状态
{
	FB->Done = false;
	FB->Error = false;
	FB->ErrorID = 0;
}

if(FB->Execute && !FB->execute_before)
{
    if(FB->Axis_num >= AXIS_MAXNUM)
	{
		FB->Error = true;
		FB->ErrorID = ParameterError;
	}
	else
    {
        *AxisEnable = true;
        if(*state != MC_Errorstop && *state != MC_Standstill && *state != MC_Disabled)
        {
            FB->Error = true;
			FB->ErrorID = StateError;
        }
        else
        {
            FB->Error = false;
            FB->ErrorID = NoError;
        }

    }

    if(!FB->Error)
    {
        *rstflag = 1;//rstflag = 1，表示向smallsystem发送复位请求，由smallsystem完成复位动作
        busy = 1;//进行复位
    }
    //console_printf("MC_Reset: Axis %d reset command , FB->Error = %d ! \n ", FB->Axis_num,FB->Error) ;
}

if (busy) /* 2022年4月12日 modi 因为没有busy可用，暂时将exebef（execute_before）的最高位当作busy，只将rstflag = 1，表示向smallsystem发送复位请求，由smallsystem完成复位动作 */
{
    *axis_busy = 0;
    *now_motion_vel = 0;

    *state = MC_Disabled;
    *run_numberm  = 0;//轴上没有运动
    *torque_run_numberm = 0;
    *couping_mode = 0;
    *now_motion_direction = 0;
    *blending_v = 0;
    *buffered_without_blending = 0;
    *buffer_busy = 0;
   if ((*statusword & SwFault) != SwFault && *statusword != 0 )//没有故障
    {
        FB->Done = true;
        FB->Error = false;
        FB->ErrorID = 0;
        busy = 0;
    }
    else
    {
            FB->Error = true;
			FB->ErrorID = StateError;
    }

}
FB->execute_before = (FB->Execute + (busy << 7) );//最高位保存busy变量

FB->Axis_numOut = FB->Axis_num;

#endif
}

FBDMC_Reset(ePLCKernalSta *Task, Uint32 FBIndex,struct MC_Reset *FB){
/*Separator--*--Separator--*--Separator*/
//FBDMC_Reset
#ifndef _CASS_PRECOMPILE_




//20240901修改位置相关变量单精度为双精度，包括引脚和临时变量

uint8_t *state = (uint8_t*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + STATE]);
uint8_t *AxisEnable = (uint8_t*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + AXIS_ENABLE]);
uint8_t *run_numberm = (uint8_t*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + RUN_NUMBERM]);
unsigned short *driver_controlword = (unsigned short*)(&CassMem[DRIVER_BASE + DRIVER_SIZE * FB->Axis_num + DRIVER_CONTROLWORD]);
unsigned short *statusword = (unsigned short*)(&CassMem[DRIVER_BASE + DRIVER_SIZE * FB->Axis_num + DRIVER_STATUSWORD]);
uint8_t *rstflag = (uint8_t*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + RST_FLAG]);
uint8_t *couping_mode = (uint8_t*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + COUPING_MODE]);

uint8_t *torque_run_numberm = (uint8_t*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + TORQUE_RUN_NUMBER]);

float *now_velocity_s = (float*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + NOW_VELOCITY_S]);

uint8_t *axis_busy = (uint8_t*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + AXIS_BUSY]);

int32_t *now_motion_direction = (int32_t*)(&CassMem[AXIS_BASE + AXIS_SIZE*FB->Axis_num + NOW_MOTION_DIRECTION]);
float *blending_v = (float*)(&CassMem[AXIS_BASE + AXIS_SIZE*FB->Axis_num + BLENDING_V]);
float *now_motion_vel = (float*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + NOW_MOTION_VEL]);
uint8_t *buffered_without_blending = (uint8_t*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + BUFFERED_WITHOUT_BLENDING]);
uint8_t *buffer_busy = (uint8_t*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + BUFFER_BUSY]);

Uint8 busy;
//结构体里没有busy变量。只能从exebef变量的字节中借一个！！！功能块的结构是定死的，没法加变量！！！！！
busy = (FB->execute_before >> 7);/* 2022年4月12日 modi 因为没有busy可用，暂时将exebef（execute_before）的最高位当作busy，只将rstflag = 1，表示向smallsystem发送复位请求，由smallsystem完成复位动作 */
FB->execute_before &= 0x7f;

if(!FB->Execute)//不在被使用状态
{
	FB->Done = false;
	FB->Error = false;
	FB->ErrorID = 0;
}

if(FB->Execute && !FB->execute_before)
{
    if(FB->Axis_num >= AXIS_MAXNUM)
	{
		FB->Error = true;
		FB->ErrorID = ParameterError;
	}
	else
    {
        *AxisEnable = true;
        if(*state != MC_Errorstop && *state != MC_Standstill && *state != MC_Disabled)
        {
            FB->Error = true;
			FB->ErrorID = StateError;
        }
        else
        {
            FB->Error = false;
            FB->ErrorID = NoError;
        }

    }

    if(!FB->Error)
    {
        *rstflag = 1;//rstflag = 1，表示向smallsystem发送复位请求，由smallsystem完成复位动作
        busy = 1;//进行复位
    }
    //console_printf("MC_Reset: Axis %d reset command , FB->Error = %d ! \n ", FB->Axis_num,FB->Error) ;
}

if (busy) /* 2022年4月12日 modi 因为没有busy可用，暂时将exebef（execute_before）的最高位当作busy，只将rstflag = 1，表示向smallsystem发送复位请求，由smallsystem完成复位动作 */
{
    *axis_busy = 0;
    *now_motion_vel = 0;

    *state = MC_Disabled;
    *run_numberm  = 0;//轴上没有运动
    *torque_run_numberm = 0;
    *couping_mode = 0;
    *now_motion_direction = 0;
    *blending_v = 0;
    *buffered_without_blending = 0;
    *buffer_busy = 0;
   if ((*statusword & SwFault) != SwFault && *statusword != 0 )//没有故障
    {
        FB->Done = true;
        FB->Error = false;
        FB->ErrorID = 0;
        busy = 0;
    }
    else
    {
            FB->Error = true;
			FB->ErrorID = StateError;
    }

}
FB->execute_before = (FB->Execute + (busy << 7) );//最高位保存busy变量

FB->Axis_numOut = FB->Axis_num;

#endif
}

FBDMC_AddAxisToGroup(ePLCKernalSta *Task, Uint32 FBIndex,struct MC_AddAxisToGroup *FB){
/*Separator--*--Separator--*--Separator*/

#ifndef _CASS_PRECOMPILE_
	struct AXESGROUP * axesgroup = &AxesGroup_Mem[FB->AxesGroup];
	uint8_t *axis_sum_ingroup = (uint8_t*)(&axesgroup->ui8_Axis_Sum_In_Group);
	uint8_t *axesgroup_state = (uint8_t*)(&axesgroup->ui8_AxesGroup_State);
	int16_t *axis_num_ingroup = (int16_t*)(axesgroup->i16_Axis_Num_In_Group);

    uint8_t *axesgroup_kin = (uint8_t*)(&axesgroup->ui8_Kin_Transform);
    uint8_t *axesgroup_kin_axissum = (uint8_t*)(&axesgroup->ui8_Kin_Axis_Sum);


	if( FB->Execute && (!FB->execute_before))
	{
        //rt_printf("#1\n");
		//先判断该轴组是否已经被创建，如果没有则先创建轴组，进行轴组初始化
		//再判断该轴组错误
		//2022.11.19修改：创建轴组以及轴组初始化的功能在smallsystem内实现（使用static，保证只初始化一次，此时轴组的valid是0）;因此，现在只需要把valid置为1

        if(axesgroup->ui8_Valid != 1)
        {
            //rt_printf("#2\n");
            axesgroup->ui8_Valid = 1;
            axesgroup->ui8_AxesGroup_Num = FB->AxesGroup;
        }
		//if(*axis_state !=  MC_Standstill || (*axesgroup_state != MC_GroupDisabled && *axesgroup_state != MC_GroupStandby))
		if(*axesgroup_state != MC_GroupDisabled )//轴组必须要在disabled状态才能添加轴
		{
            //rt_printf("#3 *axis_state = %d  *axesgroup_state = %d\n",*axis_state,*axesgroup_state);
			FB->Error = true;
			FB->ErrorID = StateError;
		}
		else
		{
            //rt_printf("#4\n");
			if(FB->IdentInGroup >= AXIS_MAXID_INGROUP|| FB->IdentInGroup < AXIS_MINID_INGROUP || FB->Axis >= AXIS_MAXNUM|| FB->Axis < 0 || FB->AxesGroup >= AXESGROUP_MAXNUM || FB->AxesGroup < AXESGROUP_MINNUM)
			{
				FB->Error = true;
				FB->ErrorID = ParameterError;
			}
			else
			{
                //rt_printf("#5\n");
				//在判断该轴组内标识符是否已经被使用，如果被使用则报参数错误
				if(axis_num_ingroup[FB->IdentInGroup] != AXIS_IDLEID_INGROUP)
				{
				    FB->Error = true;
					FB->ErrorID = ParameterError;
					FB->Busy = false;
                    FB->run_flag = false;
				}
				else
				{
                    //rt_printf("#6\n");
				    FB->Error = false;
					FB->ErrorID = NoError;
					FB->Busy = true;
					FB->run_flag = true;

				    ///轴组内标识符没有被使用，判断改单轴是否已经在轴组内，如果在则报错！！！！！！！！！
				    for(int id = 0; id < *axis_sum_ingroup; id++)
                    {
                        if(FB->Axis == axis_num_ingroup[id])
                        {
                            FB->Error = true;
                            FB->ErrorID = ParameterError;
                            FB->Busy = false;
                            FB->run_flag = false;
                            break;
                        }
                    }
                    ///判断是否绑定运动学模型，如果已经绑定，需要判断轴数+1是否超过模型规定的单轴数目
                    if(1>= *axesgroup_kin)//未绑定运动学模型
                    {
                        //无事发生
                    }
                    else//已经绑定运动学模型
                    {
                        if((*axis_sum_ingroup +1) > *axesgroup_kin_axissum)
                        {
                            FB->Error = true;
                            FB->ErrorID = AxisSum_InAxesGroup_Error;
                            FB->Busy = false;
                            FB->run_flag = false;
                        }
                    }

				}

			}
		}
	}
	FB->execute_before = FB->Execute;

	if(FB->run_flag == true)
	{
        //rt_printf("#7\n");
		FB->run_flag = false;
		//当且仅当 组内标识符未使用，该单轴不在轴组内  才能添加进轴组
		axis_num_ingroup[FB->IdentInGroup] = (int16_t)FB->Axis;
		*axis_sum_ingroup += 1;

		//*axis_state = MC_Synchronized_Motion;
		FB->Done = true;
		FB->Busy = false;
	}

	if(!FB->Execute)//不是上跳沿=》该模块不在使用
	{
		FB->Done = false;
		FB->Error = false;
		FB->ErrorID = NoError;
		FB->run_flag = false;
		FB->Busy = false;
	}

	FB->AxisOut = FB->Axis;
	FB->AxesGroupOut = FB->AxesGroup;
#endif
}

FBDMC_GroupEnable(ePLCKernalSta *Task, Uint32 FBIndex,struct MC_GroupEnable *FB){
/*Separator--*--Separator--*--Separator*/

#ifndef _CASS_PRECOMPILE_
	struct AXESGROUP * axesgroup = &AxesGroup_Mem[FB->AxesGroup];
	uint8_t axis_sum_ingroup = axesgroup->ui8_Axis_Sum_In_Group;
	uint8_t *axesgroup_state = (uint8_t*)(&axesgroup->ui8_AxesGroup_State);
    int16_t *axis_num_ingroup = (int16_t *) (axesgroup->i16_Axis_Num_In_Group);
    uint8_t axesgroup_kin_axissum = axesgroup->ui8_Kin_Axis_Sum;
    uint8_t axesgroup_kin = axesgroup->ui8_Kin_Transform;

    uint8_t *axis_state;
    int axis_n;
	if( FB->Execute && (!FB->execute_before))
	{
		if(FB->AxesGroup >= AXESGROUP_MAXNUM || FB->AxesGroup < AXESGROUP_MINNUM)
		{
			FB->Error = true;
			FB->ErrorID = ParameterError;
		}
		else
		{
			if(*axesgroup_state == MC_GroupErrorstop)
			{
				FB->Error = true;
				FB->ErrorID = StateError;
			}
			else
			{
                for(int id =0; id < axis_sum_ingroup; id++)
                {
                    axis_n = axis_num_ingroup[id];
                    axis_state = (uint8_t*)(&CassMem[AXIS_BASE + AXIS_SIZE * axis_n + STATE]);
                    if(*axis_state !=  MC_Standstill)
                    {//单轴使能成功，才能使能轴组
                        FB->Error = true;
                        FB->ErrorID = id * pow(2,AXIS_ERRORID_LEFT_BITS) + Axis_SyncMotion_StateError;
                        break;
                    }
                }

                if(FB->Error != true)
                {
                    if(0 == axesgroup_kin)
                    {//必须绑定运动学模型
                        FB->Error = true;
                        FB->ErrorID = KinTransform_ParameterError;
                    }else
                    {
                        if(axis_sum_ingroup != axesgroup_kin_axissum)
                        {//轴组内单轴数必须和运动学模型单轴数相等
                            FB->Error = true;
                            FB->ErrorID =  AxisSum_InAxesGroup_Error;
                        }
                        else
                        {
                            FB->Error = false;
                            FB->ErrorID = NoError;
                            FB->Busy = true;
                            FB->run_flag = true;
                        }
                    }

                }

			}
		}

	}
	FB->execute_before = FB->Execute;

	if(FB->run_flag == true)
	{
		FB->run_flag = false;
		if(*axesgroup_state == MC_GroupDisabled) //如果是禁用状态，则更改为静止待机状态；其他状态则不发生改变
		{
			*axesgroup_state = MC_GroupStandby;
		}

		if(*axesgroup_state == MC_GroupStandby) //标准里规定：仅在轴组状态为MC_GroupStandby时，FB->Done才为true
		{
            axesgroup->ui8_AxesGroup_Busy = 0;         /**ui8 当前轴组忙碌标志 */
            axesgroup->ui8_AxesGroup_Buffer_Busy = 0;     /**ui8  轴组的缓冲区是否繁忙*/
			FB->Done = true;
		}
		FB->Busy = false;
	}

	if(!FB->Execute )//不是上跳沿，不在执行管理任务=》该模块不在使用
	{
		FB->Done = false;
		FB->Error = false;
		FB->ErrorID = NoError;
		FB->run_flag = false;
		FB->Busy = false;
	}

	FB->AxesGroupOut = FB->AxesGroup;
#endif
}

FBDMC_Power(ePLCKernalSta *Task, Uint32 FBIndex,struct MC_Power *FB){
/*Separator--*--Separator--*--Separator*/
//MC_Power


#ifndef _CASS_PRECOMPILE_
//20240901修改位置相关变量单精度为双精度，包括引脚和临时变量
uint8_t *state = (uint8_t*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + STATE]);
uint8_t *AxisEnable = (uint8_t*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + AXIS_ENABLE]);
unsigned short *controlword = (unsigned short*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + CONTROLWORD]);
unsigned short *statusword = (unsigned short*)(&CassMem[DRIVER_BASE + DRIVER_SIZE * FB->Axis_num + DRIVER_STATUSWORD]);
short int *mode = (short int*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + MODE]);
short int *display_mode = (short int*)(&CassMem[DRIVER_BASE + DRIVER_SIZE * FB->Axis_num + DRIVER_MODES_DISPLAY]);
uint8_t *rstflag = (uint8_t*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + RST_FLAG]);
uint32_t *write_target_position = (uint32_t*)(&CassMem[DRIVER_BASE + DRIVER_SIZE * FB->Axis_num + DRIVER_TARGETPOSITION]);
int32_t *write_target_velocity = (int32_t*)(&CassMem[DRIVER_BASE + DRIVER_SIZE * FB->Axis_num + DRIVER_TARGETVELOCITY]);
int32_t *actual_position = (int32_t*)(&CassMem[DRIVER_BASE + DRIVER_SIZE * FB->Axis_num + DRIVER_ACTUAL_POSITION]);
double *now_position = (double*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + NOW_POSITION]);
double *now_motion_aimpos = (double*)(&CassMem[AXIS_BASE + AXIS_SIZE*FB->Axis_num + NOW_MOTION_AIMPOS]);
double *target_position = (double*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + TARGET_POSITION]);
double *sup_position = (double*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + SUP_POSITION]);
double *relative_position = (double*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + RELATIVE_POSITION]);
uint8_t *buffer_busy = (uint8_t*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + BUFFER_BUSY]);
double *last_target_position = (double*)(&CassMem[AXIS_BASE + AXIS_SIZE*FB->Axis_num + LAST_TARGET_POSITION]);
float *now_velocity_s = (float*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + NOW_VELOCITY_S]);
double *torque_last_read_pos = (double*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + TORQUE_LAST_READ_POS]);
float *torque_last_velocity = (float*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + TORQUE_LAST_VELOCITY]);
uint8_t *run_numberm = (uint8_t*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + RUN_NUMBERM]);


double *phaing_target_position = (double*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + PHASING_TARGET_POSITION]);
double *phaing_now_position = (double*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + PHASING_NOW_POSITION]);
uint8_t *phasing_buffer = (uint8_t*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + PHASING_BUFFER]);
uint8_t *phasing_busy = (uint8_t*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + PHASING_BUSY]);
uint8_t *phasing_run_number = (uint8_t*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + PHASING_RUN_NUMBER]);


//if(*state != MC_Errorstop)
//{
//    FB->Error = false;
//    FB->ErrorID = NoError;
//}
	//判断使能是否成功
if((*statusword  & SwEnabled) == SwEnabled && (*statusword & SwFault) != SwFault)										//显示当前实际状态
{//伺服驱动器已经运行且无故障
	FB->Valid = true;//使能成功
    FB->Error = 0 ;
    FB->ErrorID = NoError;
	if(*state == MC_Disabled)//判断轴状态  轴状态：禁用—>待机
   	{
       *state = MC_Standstill;
   	}
}
else
{//伺服驱动器不在运行或有故障
	FB->Valid = false;
    *run_numberm = 0;
	if(*state != MC_Errorstop)//轴没有错误，为禁用状态
	{
 		*state = MC_Disabled;
	}
}
//开始使能过程
if(FB->run_flag)//run_flag协助判断enable是否对驱动器使能完成，1、 run_flag为true表示enable 0->1，对驱动器进行使能，2、驱动器使能完成后变为flase，或者表示未在进行使能
{
	FB->PowerOnTimeOver += (float)Task->taskPeriod / 1000;
	if (FB->PowerOnTimeOver > 3000 ) //5s钟初始化失败
	{
      //  console_printf("--2--PowerOn enabled cmd ,AxisNo= %d *state = %d,*rstflag = %d,FB->run_flag=%d,FB->PowerOnTimeOver=%f\n",FB->Axis_num,*state,*rstflag,FB->run_flag,FB->PowerOnTimeOver) ;
		FB->Error = true;
		FB->ErrorID = StateError;
		FB->Valid = 0 ;
		FB->run_flag = false;
	}
	if((*statusword  & SwEnabled) != SwEnabled)//使能未完成，开始进行驱动器使能，驱动器从初始化状态到运行状态需要经历多个状态
	{

		*phaing_target_position = 0;
		*phaing_now_position = 0;
		*phasing_buffer = 0;
		*phasing_busy = 0;
		*phasing_run_number = 0;

		*target_position = *now_position;
		*last_target_position = *target_position;
		*now_motion_aimpos = *now_position;
		*sup_position = 0;
		*torque_last_read_pos = *actual_position;
		*torque_last_velocity = 0;
		*write_target_velocity = 0;
		*now_velocity_s = 0;
		*buffer_busy = 0;
		*run_numberm = 0;

		//对驱动器进行使能，按序的状态过渡
		if((*statusword  & Enabled_Ready) == Enabled_Ready && (*statusword & SwFault) != SwFault)//
		{
			*controlword = ((*controlword & 0xFF00) | ENABLED);
		}
		else if((*statusword  & Switch_Ready) == Switch_Ready && (*statusword & SwFault) != SwFault)
		{
			*controlword = ((*controlword & 0xFF00) |Switch_On);
		}
		// else if((*statusword  & Ready_Enabled) == Ready_Enabled && (*statusword & SwFault) != SwFault) 2022年4月12日 modi!
		else if((*statusword & SwFault) != SwFault)
		{
			*controlword = ((*controlword & 0xFF00) |Shut_Down);
		}
	}
	else if((*statusword  & SwEnabled) == SwEnabled && (*statusword & SwFault) != SwFault)		//enabled  使能完成
	{
	  //  console_printf("MC_Power #1 : FB->Axis_num =%d FB->Valid = %d,*target_position=%lf,*now_position=%lf\n",FB->Axis_num,FB->Valid,*target_position,*now_position);
		FB->run_flag = false;
		*target_position = *now_position;
		*last_target_position = *now_position;
		*now_motion_aimpos =  *now_position;
      //  console_printf("MC_Power #2: FB->Axis_num =%d FB->Valid = %d,*target_position=%lf,*now_position=%lf\n",FB->Axis_num,FB->Valid,*target_position,*now_position);
	}

}
//判断是使能还是失能
if(FB->Enable && !FB->run_flag)								//使能
{

	if(*state == MC_Errorstop)//判断轴是否在errorstop状态
	{
       FB->Valid = false;
	   FB->Error = true;
	   FB->ErrorID = StateError;
	}
	else if(*rstflag == 0 && !FB->Valid)//复位标志为0，不在复位状态
	{
	   FB->run_flag = true;  //开始进行使能，也就是上面部分代码的步骤！！
           *AxisEnable = true;
	   FB->PowerOnTimeOver = 0 ;
       //console_printf("--1--PowerOn enabled cmd ,AxisNo=%d *state = %d,*rstflag = %d,FB->run_flag=%d,FB->PowerOnTimeOver=%f\n",FB->Axis_num,*state,*rstflag,FB->run_flag,FB->PowerOnTimeOver) ;
	}

}
else if(!FB->Enable)						//失能
{
	*controlword = ((*controlword & 0xFF00) | Disable);//通过控制字对驱动器进行控制disable
	if(*state != MC_Errorstop && *state != MC_Disabled)//如果轴没有错误，改为disable状态
	{
	   *state = MC_Disabled;
	  // console_printf("--0--PowerOn enabled cmd ,,AxisNo=%d *state = %d,*rstflag = %d,FB->run_flag=%d,FB->PowerOnTimeOver=%f\n",FB->Axis_num,*state,*rstflag,FB->run_flag,FB->PowerOnTimeOver) ;
	}
    FB->run_flag = false;
    FB->Error = false;
    FB->ErrorID = 0;
    FB->Valid = 0 ;
    *statusword = 0 ;   //未使能的情况下强行修改驱动器状态字，不得启动运动（主要解决Ethercat断掉的情况下此值强制0）
}
//驱动器控制模式
//--------------------------2024年6月15日修改，注释掉模式判断，由用户自己保证输入的模式的正确性
*mode = FB->Mode;
//--------------------------2024-06-15

FB->Now_mode = *display_mode;//当前的驱动器控制模式=从驱动器读取的控制模式
FB->Axis_numOut = FB->Axis_num;//轴号不发生改变
#endif
}

FBDMC_Power(ePLCKernalSta *Task, Uint32 FBIndex,struct MC_Power *FB){
/*Separator--*--Separator--*--Separator*/
//MC_Power


#ifndef _CASS_PRECOMPILE_
//20240901修改位置相关变量单精度为双精度，包括引脚和临时变量
uint8_t *state = (uint8_t*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + STATE]);
uint8_t *AxisEnable = (uint8_t*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + AXIS_ENABLE]);
unsigned short *controlword = (unsigned short*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + CONTROLWORD]);
unsigned short *statusword = (unsigned short*)(&CassMem[DRIVER_BASE + DRIVER_SIZE * FB->Axis_num + DRIVER_STATUSWORD]);
short int *mode = (short int*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + MODE]);
short int *display_mode = (short int*)(&CassMem[DRIVER_BASE + DRIVER_SIZE * FB->Axis_num + DRIVER_MODES_DISPLAY]);
uint8_t *rstflag = (uint8_t*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + RST_FLAG]);
uint32_t *write_target_position = (uint32_t*)(&CassMem[DRIVER_BASE + DRIVER_SIZE * FB->Axis_num + DRIVER_TARGETPOSITION]);
int32_t *write_target_velocity = (int32_t*)(&CassMem[DRIVER_BASE + DRIVER_SIZE * FB->Axis_num + DRIVER_TARGETVELOCITY]);
int32_t *actual_position = (int32_t*)(&CassMem[DRIVER_BASE + DRIVER_SIZE * FB->Axis_num + DRIVER_ACTUAL_POSITION]);
double *now_position = (double*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + NOW_POSITION]);
double *now_motion_aimpos = (double*)(&CassMem[AXIS_BASE + AXIS_SIZE*FB->Axis_num + NOW_MOTION_AIMPOS]);
double *target_position = (double*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + TARGET_POSITION]);
double *sup_position = (double*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + SUP_POSITION]);
double *relative_position = (double*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + RELATIVE_POSITION]);
uint8_t *buffer_busy = (uint8_t*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + BUFFER_BUSY]);
double *last_target_position = (double*)(&CassMem[AXIS_BASE + AXIS_SIZE*FB->Axis_num + LAST_TARGET_POSITION]);
float *now_velocity_s = (float*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + NOW_VELOCITY_S]);
double *torque_last_read_pos = (double*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + TORQUE_LAST_READ_POS]);
float *torque_last_velocity = (float*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + TORQUE_LAST_VELOCITY]);
uint8_t *run_numberm = (uint8_t*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + RUN_NUMBERM]);


double *phaing_target_position = (double*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + PHASING_TARGET_POSITION]);
double *phaing_now_position = (double*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + PHASING_NOW_POSITION]);
uint8_t *phasing_buffer = (uint8_t*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + PHASING_BUFFER]);
uint8_t *phasing_busy = (uint8_t*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + PHASING_BUSY]);
uint8_t *phasing_run_number = (uint8_t*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + PHASING_RUN_NUMBER]);


//if(*state != MC_Errorstop)
//{
//    FB->Error = false;
//    FB->ErrorID = NoError;
//}
	//判断使能是否成功
if((*statusword  & SwEnabled) == SwEnabled && (*statusword & SwFault) != SwFault)										//显示当前实际状态
{//伺服驱动器已经运行且无故障
	FB->Valid = true;//使能成功
    FB->Error = 0 ;
    FB->ErrorID = NoError;
	if(*state == MC_Disabled)//判断轴状态  轴状态：禁用—>待机
   	{
       *state = MC_Standstill;
   	}
}
else
{//伺服驱动器不在运行或有故障
	FB->Valid = false;
    *run_numberm = 0;
	if(*state != MC_Errorstop)//轴没有错误，为禁用状态
	{
 		*state = MC_Disabled;
	}
}
//开始使能过程
if(FB->run_flag)//run_flag协助判断enable是否对驱动器使能完成，1、 run_flag为true表示enable 0->1，对驱动器进行使能，2、驱动器使能完成后变为flase，或者表示未在进行使能
{
	FB->PowerOnTimeOver += (float)Task->taskPeriod / 1000;
	if (FB->PowerOnTimeOver > 3000 ) //5s钟初始化失败
	{
      //  console_printf("--2--PowerOn enabled cmd ,AxisNo= %d *state = %d,*rstflag = %d,FB->run_flag=%d,FB->PowerOnTimeOver=%f\n",FB->Axis_num,*state,*rstflag,FB->run_flag,FB->PowerOnTimeOver) ;
		FB->Error = true;
		FB->ErrorID = StateError;
		FB->Valid = 0 ;
		FB->run_flag = false;
	}
	if((*statusword  & SwEnabled) != SwEnabled)//使能未完成，开始进行驱动器使能，驱动器从初始化状态到运行状态需要经历多个状态
	{

		*phaing_target_position = 0;
		*phaing_now_position = 0;
		*phasing_buffer = 0;
		*phasing_busy = 0;
		*phasing_run_number = 0;

		*target_position = *now_position;
		*last_target_position = *target_position;
		*now_motion_aimpos = *now_position;
		*sup_position = 0;
		*torque_last_read_pos = *actual_position;
		*torque_last_velocity = 0;
		*write_target_velocity = 0;
		*now_velocity_s = 0;
		*buffer_busy = 0;
		*run_numberm = 0;

		//对驱动器进行使能，按序的状态过渡
		if((*statusword  & Enabled_Ready) == Enabled_Ready && (*statusword & SwFault) != SwFault)//
		{
			*controlword = ((*controlword & 0xFF00) | ENABLED);
		}
		else if((*statusword  & Switch_Ready) == Switch_Ready && (*statusword & SwFault) != SwFault)
		{
			*controlword = ((*controlword & 0xFF00) |Switch_On);
		}
		// else if((*statusword  & Ready_Enabled) == Ready_Enabled && (*statusword & SwFault) != SwFault) 2022年4月12日 modi!
		else if((*statusword & SwFault) != SwFault)
		{
			*controlword = ((*controlword & 0xFF00) |Shut_Down);
		}
	}
	else if((*statusword  & SwEnabled) == SwEnabled && (*statusword & SwFault) != SwFault)		//enabled  使能完成
	{
	  //  console_printf("MC_Power #1 : FB->Axis_num =%d FB->Valid = %d,*target_position=%lf,*now_position=%lf\n",FB->Axis_num,FB->Valid,*target_position,*now_position);
		FB->run_flag = false;
		*target_position = *now_position;
		*last_target_position = *now_position;
		*now_motion_aimpos =  *now_position;
      //  console_printf("MC_Power #2: FB->Axis_num =%d FB->Valid = %d,*target_position=%lf,*now_position=%lf\n",FB->Axis_num,FB->Valid,*target_position,*now_position);
	}

}
//判断是使能还是失能
if(FB->Enable && !FB->run_flag)								//使能
{

	if(*state == MC_Errorstop)//判断轴是否在errorstop状态
	{
       FB->Valid = false;
	   FB->Error = true;
	   FB->ErrorID = StateError;
	}
	else if(*rstflag == 0 && !FB->Valid)//复位标志为0，不在复位状态
	{
	   FB->run_flag = true;  //开始进行使能，也就是上面部分代码的步骤！！
           *AxisEnable = true;
	   FB->PowerOnTimeOver = 0 ;
       //console_printf("--1--PowerOn enabled cmd ,AxisNo=%d *state = %d,*rstflag = %d,FB->run_flag=%d,FB->PowerOnTimeOver=%f\n",FB->Axis_num,*state,*rstflag,FB->run_flag,FB->PowerOnTimeOver) ;
	}

}
else if(!FB->Enable)						//失能
{
	*controlword = ((*controlword & 0xFF00) | Disable);//通过控制字对驱动器进行控制disable
	if(*state != MC_Errorstop && *state != MC_Disabled)//如果轴没有错误，改为disable状态
	{
	   *state = MC_Disabled;
	  // console_printf("--0--PowerOn enabled cmd ,,AxisNo=%d *state = %d,*rstflag = %d,FB->run_flag=%d,FB->PowerOnTimeOver=%f\n",FB->Axis_num,*state,*rstflag,FB->run_flag,FB->PowerOnTimeOver) ;
	}
    FB->run_flag = false;
    FB->Error = false;
    FB->ErrorID = 0;
    FB->Valid = 0 ;
    *statusword = 0 ;   //未使能的情况下强行修改驱动器状态字，不得启动运动（主要解决Ethercat断掉的情况下此值强制0）
}
//驱动器控制模式
//--------------------------2024年6月15日修改，注释掉模式判断，由用户自己保证输入的模式的正确性
*mode = FB->Mode;
//--------------------------2024-06-15

FB->Now_mode = *display_mode;//当前的驱动器控制模式=从驱动器读取的控制模式
FB->Axis_numOut = FB->Axis_num;//轴号不发生改变
#endif
}

