FBDMC_AddAxisToGroup(ePLCKernalSta *Task, Uint32 FBIndex,struct MC_AddAxisToGroup *FB){
/*Separator--*--Separator--*--Separator*/

#ifndef _CASS_PRECOMPILE_
	struct AXESGROUP * axesgroup = &AxesGroup_Mem[FB->AxesGroup];
	uint8_t *axis_sum_ingroup = (uint8_t*)(&axesgroup->ui8_Axis_Sum_In_Group);
	uint8_t *axesgroup_state = (uint8_t*)(&axesgroup->ui8_AxesGroup_State);
	int16_t *axis_num_ingroup = (int16_t*)(axesgroup->i16_Axis_Num_In_Group);

    uint8_t *axesgroup_kin = (uint8_t*)(&axesgroup->ui8_Kin_Transform);
    uint8_t *axesgroup_kin_axissum = (uint8_t*)(&axesgroup->ui8_Kin_Axis_Sum);


	if( FB->Execute && (!FB->execute_before))
	{
        //rt_printf("#1\n");
		//先判断该轴组是否已经被创建，如果没有则先创建轴组，进行轴组初始化
		//再判断该轴组错误
		//2022.11.19修改：创建轴组以及轴组初始化的功能在smallsystem内实现（使用static，保证只初始化一次，此时轴组的valid是0）;因此，现在只需要把valid置为1

        if(axesgroup->ui8_Valid != 1)
        {
            //rt_printf("#2\n");
            axesgroup->ui8_Valid = 1;
            axesgroup->ui8_AxesGroup_Num = FB->AxesGroup;
        }
		//if(*axis_state !=  MC_Standstill || (*axesgroup_state != MC_GroupDisabled && *axesgroup_state != MC_GroupStandby))
		if(*axesgroup_state != MC_GroupDisabled )//轴组必须要在disabled状态才能添加轴
		{
            //rt_printf("#3 *axis_state = %d  *axesgroup_state = %d\n",*axis_state,*axesgroup_state);
			FB->Error = true;
			FB->ErrorID = StateError;
		}
		else
		{
            //rt_printf("#4\n");
			if(FB->IdentInGroup >= AXIS_MAXID_INGROUP|| FB->IdentInGroup < AXIS_MINID_INGROUP || FB->Axis >= AXIS_MAXNUM|| FB->Axis < 0 || FB->AxesGroup >= AXESGROUP_MAXNUM || FB->AxesGroup < AXESGROUP_MINNUM)
			{
				FB->Error = true;
				FB->ErrorID = ParameterError;
			}
			else
			{
                //rt_printf("#5\n");
				//在判断该轴组内标识符是否已经被使用，如果被使用则报参数错误
				if(axis_num_ingroup[FB->IdentInGroup] != AXIS_IDLEID_INGROUP)
				{
				    FB->Error = true;
					FB->ErrorID = ParameterError;
					FB->Busy = false;
                    FB->run_flag = false;
				}
				else
				{
                    //rt_printf("#6\n");
				    FB->Error = false;
					FB->ErrorID = NoError;
					FB->Busy = true;
					FB->run_flag = true;

				    ///轴组内标识符没有被使用，判断改单轴是否已经在轴组内，如果在则报错！！！！！！！！！
				    for(int id = 0; id < *axis_sum_ingroup; id++)
                    {
                        if(FB->Axis == axis_num_ingroup[id])
                        {
                            FB->Error = true;
                            FB->ErrorID = ParameterError;
                            FB->Busy = false;
                            FB->run_flag = false;
                            break;
                        }
                    }
                    ///判断是否绑定运动学模型，如果已经绑定，需要判断轴数+1是否超过模型规定的单轴数目
                    if(1>= *axesgroup_kin)//未绑定运动学模型
                    {
                        //无事发生
                    }
                    else//已经绑定运动学模型
                    {
                        if((*axis_sum_ingroup +1) > *axesgroup_kin_axissum)
                        {
                            FB->Error = true;
                            FB->ErrorID = AxisSum_InAxesGroup_Error;
                            FB->Busy = false;
                            FB->run_flag = false;
                        }
                    }

				}

			}
		}
	}
	FB->execute_before = FB->Execute;

	if(FB->run_flag == true)
	{
        //rt_printf("#7\n");
		FB->run_flag = false;
		//当且仅当 组内标识符未使用，该单轴不在轴组内  才能添加进轴组
		axis_num_ingroup[FB->IdentInGroup] = (int16_t)FB->Axis;
		*axis_sum_ingroup += 1;

		//*axis_state = MC_Synchronized_Motion;
		FB->Done = true;
		FB->Busy = false;
	}

	if(!FB->Execute)//不是上跳沿=》该模块不在使用
	{
		FB->Done = false;
		FB->Error = false;
		FB->ErrorID = NoError;
		FB->run_flag = false;
		FB->Busy = false;
	}

	FB->AxisOut = FB->Axis;
	FB->AxesGroupOut = FB->AxesGroup;
#endif
}

