            *maxjerk[FB->i] = 1000000000.0;
            *homevelocity[FB->i] = *homeacceleration[FB->i] = *homedeceleration[FB->i] = *homejerk[FB->i] = 80000;//写进AXIS
            *home_slow_velocity[FB->i] = 1000;//写进AXIS
            *velFactor[FB->i] = 1.0;
            *accFactor[FB->i] = 1.0;
            *jerkFactor[FB->i] = 1.0;
