            positive_torque_limit[FB->i] = (unsigned short *) (&CassMem[DRIVER_BASE + DRIVER_SIZE * FB->i +
                                                                        DRIVER_POSITIVE_TORQUE_LIMIT]);
            negative_torque_limit[FB->i] = (unsigned short *) (&CassMem[DRIVER_BASE + DRIVER_SIZE * FB->i +
                                                                        DRIVER_NEGATIVE_TORQUE_LIMIT]);
            //这些数组都是指针数组，可读可写  下面是AXIS
//            axis_num[FB->i] = (uint8_t *) (&CassMem[AXIS_BASE + AXIS_SIZE * FB->i + AXIS_NUM]);
//            *axis_num[FB->i] = FB->i;//轴的编号从0到AXISAXIS_MAXNUM-1
            state[FB->i] = (uint8_t *) (&CassMem[AXIS_BASE + AXIS_SIZE * FB->i + STATE]);
            AxisEnable[FB->i]= (uint8_t*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->i + AXIS_ENABLE]);
            controlword[FB->i] = (unsigned short *) (&CassMem[AXIS_BASE + AXIS_SIZE * FB->i + CONTROLWORD]);
            statusword[FB->i] = (short int *) (&CassMem[AXIS_BASE + AXIS_SIZE * FB->i + STATUSWORD]);
            mode[FB->i] = (short int *) (&CassMem[AXIS_BASE + AXIS_SIZE * FB->i + MODE]);
            now_position[FB->i] = (double *) (&CassMem[AXIS_BASE + AXIS_SIZE * FB->i + NOW_POSITION]);
            sup_position[FB->i] = (double *) (&CassMem[AXIS_BASE + AXIS_SIZE * FB->i + SUP_POSITION]);
            relative_position[FB->i] = (double *) (&CassMem[AXIS_BASE + AXIS_SIZE * FB->i + RELATIVE_POSITION]);
